#[cfg(windows)]
use windows::core::PCWSTR;
#[cfg(windows)]
use windows::Win32::System::Threading::AvSetMmThreadCharacteristicsW;

/// Configures CPU control registers for Flush-to-Zero (FTZ) and Denormals-are-Zero (DAZ).
/// On x86/x86_64, subnormal floating point numbers generated by recursive IIR biquad filters
/// or adaptive algorithms cause hardware microcode exception penalties (100+ cycle stalls).
/// Enabling FTZ and DAZ ensures subnormals are flushed to 0.0 in a single clock cycle.
#[inline(always)]
#[allow(deprecated)]
pub fn enable_ftz_daz() {
    #[cfg(target_arch = "x86_64")]
    unsafe {
        use std::arch::x86_64::{_mm_getcsr, _mm_setcsr};
        let mut mxcsr = _mm_getcsr();
        mxcsr |= 0x8000 | 0x0040; // 0x8000: FTZ, 0x0040: DAZ
        _mm_setcsr(mxcsr);
    }
    #[cfg(target_arch = "x86")]
    unsafe {
        use std::arch::x86::{_mm_getcsr, _mm_setcsr};
        let mut mxcsr = _mm_getcsr();
        mxcsr |= 0x8000 | 0x0040;
        _mm_setcsr(mxcsr);
    }
}

/// Windows MMCSS (Multimedia Class Scheduler Service) registration handle.
/// Guarantees that the dedicated audio processing thread receives "Pro Audio" high-priority scheduling
/// to prevent dropouts, buffer starvation, or latency spikes caused by background Windows processes.
pub struct MmcssHandle {
    #[cfg(windows)]
    _task_index: u32,
    #[cfg(windows)]
    handle: windows::Win32::Foundation::HANDLE,
}

impl MmcssHandle {
    /// Registers the calling thread with Windows MMCSS under the "Pro Audio" profile
    /// and configures hardware FTZ/DAZ subnormal execution.
    pub fn register_pro_audio() -> Result<Self, String> {
        enable_ftz_daz();

        #[cfg(windows)]
        unsafe {
            let mut task_index = 0u32;
            let class_name: Vec<u16> = "Pro Audio\0".encode_utf16().collect();
            let handle = AvSetMmThreadCharacteristicsW(PCWSTR(class_name.as_ptr()), &mut task_index)
                .map_err(|e| format!("AvSetMmThreadCharacteristicsW failed: {}", e))?;

            tracing::info!("Registered audio processing thread with MMCSS 'Pro Audio' (task_index={})", task_index);
            Ok(Self { _task_index: task_index, handle })
        }

        #[cfg(not(windows))]
        {
            Ok(Self {})
        }
    }
}

impl Drop for MmcssHandle {
    fn drop(&mut self) {
        #[cfg(windows)]
        unsafe {
            if !self.handle.is_invalid() {
                let _ = windows::Win32::System::Threading::AvRevertMmThreadCharacteristics(self.handle);
                tracing::info!("Reverted MMCSS Pro Audio thread characteristics");
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    #[allow(deprecated)]
    fn test_ftz_daz_enabled() {
        enable_ftz_daz();
        #[cfg(target_arch = "x86_64")]
        unsafe {
            use std::arch::x86_64::_mm_getcsr;
            let mxcsr = _mm_getcsr();
            assert_ne!(mxcsr & 0x8000, 0, "FTZ bit must be set");
            assert_ne!(mxcsr & 0x0040, 0, "DAZ bit must be set");
        }
    }
}
